    },
    {
      "name": "Real.sum_log_le",
      "type": " {x : ℝ} (hx : 1 ≤ x) : ∑ n ∈ Finset.Ioc 0 ⌊x⌋₊, Real.log ↑n ≤ x * Real.log x - x + Real.log x + 1",
