    },
    {
      "name": "Real.le_sum_log'",
      "type": " {x : ℝ} (hx : 1 ≤ x) : x * Real.log x - 2 * x ≤ ∑ n ∈ Finset.Ioc 0 ⌊x⌋₊, Real.log ↑n",
      "module": "Mathlib.Analysis.SpecialFunctions.Log.Sum"
    },
    {
      "name": "sum_div_nat_floor_pow_sq_le_div_sq",
      "type": " (N : ℕ) {j : ℝ} (hj : 0 < j) {c : ℝ} (hc : 1 < c) : ∑ i ∈ Finset.range N with j < ↑⌊c ^ i⌋₊, 1 / ↑⌊c ^ i⌋₊ ^ 2 ≤ c ^ 5 * (c - 1)⁻¹ ^ 3 / j ^ 2",
      "module": "Mathlib.Analysis.SpecificLimits.FloorPow"
    },
    {
      "name": "integrableOn_mul_sum_Icc",
      "type": " {𝕜 : Type u_1} [RCLike 𝕜] (c : ℕ → 𝕜) {a b : ℝ} {m : ℕ} (ha : 0 ≤ a) {g : ℝ → 𝕜} (hg_int : MeasureTheory.IntegrableOn g (Set.Icc a b) MeasureTheory.volume) : MeasureTheory.IntegrableOn (fun t => g t * ∑ k ∈ Finset.Icc m ⌊t⌋₊, c k) (Set.Icc a b) MeasureTheory.volume",
      "module": "Mathlib.NumberTheory.AbelSummation"
    },
    {
      "name": "locallyIntegrableOn_mul_sum_Icc",
      "type": " {𝕜 : Type u_1} [RCLike 𝕜] (c : ℕ → 𝕜) {a : ℝ} {m : ℕ} (ha : 0 ≤ a) {g : ℝ → 𝕜} (hg : MeasureTheory.LocallyIntegrableOn g (Set.Ici a) MeasureTheory.volume) : MeasureTheory.LocallyIntegrableOn (fun t => g t * ∑ k ∈ Finset.Icc m ⌊t⌋₊, c k) (Set.Ici a) MeasureTheory.volume",
      "module": "Mathlib.NumberTheory.AbelSummation"
    },
    {
      "name": "sum_mul_eq_sub_integral_mul",
      "type": " {𝕜 : Type u_1} [RCLike 𝕜] (c : ℕ → 𝕜) {f : ℝ → 𝕜} {b : ℝ} (hb : 0 ≤ b) (hf_diff : ∀ t ∈ Set.Icc 0 b, DifferentiableAt ℝ f t) (hf_int : MeasureTheory.IntegrableOn (deriv f) (Set.Icc 0 b) MeasureTheory.volume) : ∑ k ∈ Finset.Icc 0 ⌊b⌋₊, f ↑k * c k = f b * ∑ k ∈ Finset.Icc 0 ⌊b⌋₊, c k - ∫ (t : ℝ) in Set.Ioc 0 b, deriv f t * ∑ k ∈ Finset.Icc 0 ⌊t⌋₊, c k",
      "module": "Mathlib.NumberTheory.AbelSummation"
    }
  ]
